<?php
require __DIR__ . '/auth.php'; requireLogin();
$report=$_GET['report']??'';$year=(int)($_GET['year']??date('Y'));$month=(int)($_GET['month']??date('n'));$start=$end='';
function reportDate($v){$t=strtotime($v);return $t?date('d-m-Y',$t):$v;} function validDate($v){$d=DateTime::createFromFormat('Y-m-d',$v);return $d&&$d->format('Y-m-d')===$v;}
if($report==='monthly'&&$year>=2000&&$year<=2100&&$month>=1&&$month<=12){$start=sprintf('%04d-%02d-01',$year,$month);$end=date('Y-m-t',strtotime($start));}elseif($report==='six_months'){$end=date('Y-m-d');$start=date('Y-m-d',strtotime('-5 months',strtotime(date('Y-m-01'))));}elseif($report==='yearly'&&$year>=2000&&$year<=2100){$start="$year-01-01";$end="$year-12-31";}elseif($report==='custom'){$start=$_GET['start']??'';$end=$_GET['end']??'';if(!validDate($start)||!validDate($end)||$start>$end)$start=$end='';}
$rows=[];if($start&&$end){$s=$db->prepare('SELECT id,lunch_date,meal_type,meal_time,recorded_time,food_item,quantity,notes FROM lunches WHERE user_id=? AND lunch_date BETWEEN ? AND ? ORDER BY lunch_date,meal_time,id');$s->execute([$_SESSION['user_id'],$start,$end]);$rows=$s->fetchAll();}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Food Reports</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Inter,system-ui,sans-serif}.wrap{width:min(100% - 20px,1100px);margin:auto;padding:18px 0 40px}.top{display:flex;justify-content:space-between;margin-bottom:15px}.top a{color:#1d4ed8;text-decoration:none;font-weight:800}.hero{background:linear-gradient(135deg,#0f172a,#1d4ed8);color:#fff;border-radius:22px;padding:22px;margin-bottom:15px}.hero h1{margin:0 0 5px}.hero p{margin:0;color:#dbeafe}.card{background:#fff;border:1px solid #e2e8f0;border-radius:19px;padding:19px;margin-bottom:15px;box-shadow:0 10px 30px #0f172a0d}.grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.filters{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:block;font-size:12px;font-weight:800;margin:10px 0 6px}input,select,button{width:100%;padding:12px;border:1px solid #d7dce5;border-radius:11px;font:inherit}button{background:#0f172a;color:#fff;border:0;font-weight:800;margin-top:13px}.summary{display:flex;gap:10px;flex-wrap:wrap}.pill{background:#eff6ff;color:#1d4ed8;padding:8px 11px;border-radius:99px;font-size:12px;font-weight:800}.download{display:flex;gap:9px;margin-top:15px}.download a{padding:11px 14px;background:#0f172a;color:#fff;text-decoration:none;border-radius:10px;font-size:12px;font-weight:800}.table{overflow:auto;border:1px solid #e2e8f0;border-radius:12px}table{width:100%;min-width:760px;border-collapse:collapse}th,td{padding:11px;border-bottom:1px solid #e2e8f0;text-align:left;font-size:12px}th{background:#f8fafc;color:#64748b}.empty{text-align:center;color:#64748b;padding:25px}@media(max-width:700px){.grid,.filters{grid-template-columns:1fr}.download{display:grid}.wrap{padding-top:10px}}
</style></head><body><main class="wrap"><div class="top"><a href="index.php">← Dashboard</a><a href="profile.php">👤 Profile</a></div><header class="hero"><h1>📊 Food Reports</h1><p><?=h(currentUser()['name'])?> · View and export your personal food history.</p></header><section class="grid"><div class="card"><h2>Report Filters</h2><form method="get"><div class="filters"><div><label>Report Type</label><select name="report" required><option value="">Select</option><option value="monthly" <?=$report==='monthly'?'selected':''?>>Monthly</option><option value="six_months" <?=$report==='six_months'?'selected':''?>>Last 6 Months</option><option value="yearly" <?=$report==='yearly'?'selected':''?>>Yearly</option><option value="custom" <?=$report==='custom'?'selected':''?>>Custom Range</option></select></div><div><label>Year</label><input type="number" name="year" min="2000" max="2100" value="<?=h((string)$year)"></div></div><div id="month"><label>Month</label><select name="month"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=$month===$m?'selected':''?>><?=date('F',mktime(0,0,0,$m,1))?></option><?php endfor;?></select></div><div id="custom"><label>Start Date (DD-MM-YYYY)</label><input id="sd" value="<?=$start?h(reportDate($start)):''?>" placeholder="01-09-2026"><input type="hidden" name="start" id="s" value="<?=h($start)"><label>End Date (DD-MM-YYYY)</label><input id="ed" value="<?=$end?h(reportDate($end)):''?>" placeholder="11-09-2026"><input type="hidden" name="end" id="e" value="<?=h($end)"></div><button>Generate Report</button></form></div><div class="card"><h2>Summary</h2><?php if($start&&$end):?><div class="summary"><span class="pill">Entries: <?=count($rows)?></span><span class="pill">Days: <?=count(array_unique(array_column($rows,'lunch_date')))?></span></div><p>Period: <strong><?=h(reportDate($start))?> → <?=h(reportDate($end))?></strong></p><div class="summary"><?php $counts=[];foreach($rows as $r)$counts[$r['meal_type']??'Lunch']=($counts[$r['meal_type']??'Lunch']??0)+1;foreach($counts as $n=>$c):?><span class="pill"><?=h($n)?>: <?=$c?></span><?php endforeach;?></div><div class="download"><a href="export.php?format=xlsx&start=<?=urlencode($start)?>&end=<?=urlencode($end)?>">⬇ Excel</a><a href="export.php?format=csv&start=<?=urlencode($start)?>&end=<?=urlencode($end)?>">⬇ CSV</a></div><?php else:?><div class="empty">Select a report to view your history.</div><?php endif;?></div></section><?php if($start&&$end):?><section class="card"><h2>Report Preview</h2><?php if(!$rows):?><div class="empty">No entries found.</div><?php else:?><div class="table"><table><thead><tr><th>Date</th><th>Meal</th><th>Food</th><th>Quantity</th><th>Time</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h(reportDate($r['lunch_date']))?></td><td><?=h($r['meal_type']??'Lunch')?></td><td><strong><?=h($r['food_item'])?></strong></td><td><?=h($r['quantity']??'')?></td><td><?=h($r['meal_time']??'')?></td><td><?=h($r['notes']??'')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?><script>const type=document.querySelector('[name=report]'),month=document.getElementById('month'),custom=document.getElementById('custom');function show(){month.style.display=(type.value==='monthly'||type.value==='yearly')?'block':'none';custom.style.display=type.value==='custom'?'block':'none'}type.onchange=show;show();function iso(v){const m=v.match(/^(\d{2})-(\d{2})-(\d{4})$/);if(!m)return null;const x=new Date(Date.UTC(+m[3],+m[2]-1,+m[1]));return x.getUTCFullYear()==+m[3]&&x.getUTCMonth()==+m[2]-1&&x.getUTCDate()==+m[1]?m[3]+'-'+m[2]+'-'+m[1]:null}document.querySelector('form').onsubmit=e=>{if(type.value==='custom'){const s=iso(sd.value.trim()),en=iso(ed.value.trim());if(!s||!en||s>en){e.preventDefault();alert('Enter valid DD-MM-YYYY dates.');return}s.value=s;e.value=en}};</script></main></body></html>
